namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return
        [
            new(1, "Forklift A",        "Warehouse 1", new DateTime(2026, 6, 15)),
            new(2, "Conveyor Belt B",   "Warehouse 2", new DateTime(2026, 5, 20)),
            new(3, "Pallet Jack C",     "Dock 3",      new DateTime(2026, 7, 1)),
            new(4, "Crane D",           "Yard",        new DateTime(2026, 4, 10)),
            new(5, "Compressor E",      "Maintenance", new DateTime(2026, 3, 22)),
            new(6, "Welding Rig F",     "Shop Floor",  new DateTime(2026, 6, 30)),
            new(7, "Drill Press G",     "Shop Floor",  new DateTime(2026, 2, 14)),
        ];
    }
}

@page "/inventory"
@implements IDisposable
@rendermode InteractiveServer
@inject InventoryApp.Services.EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_items), out var restored))
        {
            // First render (SSR) — fetch from the service
            _items = await EquipmentService.GetEquipmentAsync();
        }
        else
        {
            // Interactive reconnect — use the data persisted during SSR
            _items = restored;
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(nameof(_items), _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

